var account = new BankAccount("Ada", 100m);
account.Deposit(50m);
bool ok = account.Withdraw(500m);

Console.WriteLine(ok);
Console.WriteLine(account.Balance);
Console.WriteLine(account.Owner);

class BankAccount
{
    private decimal _balance;

    public string Owner { get; }
    public decimal Balance => _balance;

    public BankAccount(string owner, decimal openingBalance)
    {
        Owner = owner;
        _balance = openingBalance;
    }

    public void Deposit(decimal amount)
    {
        if (amount <= 0)
        {
            throw new ArgumentOutOfRangeException(nameof(amount), "Deposit must be positive.");
        }
        _balance += amount;
    }

    public bool Withdraw(decimal amount)
    {
        if (amount > _balance) return false;
        _balance -= amount;
        return true;
    }
}

var original = new Counter();
var alias = original;         // same object, two names
var separate = new Counter(); // a second object

original.Increment();
original.Increment();
alias.Increment();
separate.Increment();

Console.WriteLine($"original = {original.Count}, alias = {alias.Count}, separate = {separate.Count}");
Console.WriteLine(ReferenceEquals(original, alias));
Console.WriteLine(ReferenceEquals(original, separate));

class Counter
{
    public int Count { get; private set; }

    public void Increment() => Count++;
}

var a = new Ticket();
var b = new Ticket();
var c = new Ticket();

Console.WriteLine($"{a.Number} {b.Number} {c.Number}");
Console.WriteLine(Ticket.Issued);
Console.WriteLine(Ticket.Describe(b));

class Ticket
{
    private static int _nextNumber = 1;

    public static int Issued { get; private set; }
    public int Number { get; }

    public Ticket()
    {
        Number = _nextNumber++;
        Issued++;
    }

    public static string Describe(Ticket ticket) => $"Ticket #{ticket.Number} of {Issued}";
}

var book = new Book("Dune", 1965) { Pages = 412 };
Console.WriteLine(book);
Console.WriteLine(book.IsClassic(2026));

class Book(string title, int year)
{
    public string Title { get; } = title;
    public int Year { get; } = year;
    public int Pages { get; set; }

    public bool IsClassic(int currentYear) => currentYear - year >= 50;

    public override string ToString() => $"{Title} ({Year}), {Pages} pages";
}
